-- Independent concurrent index build; exact definition/readiness checked at cutover.
CREATE INDEX CONCURRENTLY IF NOT EXISTS "portal_catalog_search_flow_cas_v2_idx" ON "private"."portal_catalog_search_rows_v2" USING "btree" ((("card" ->> 'casNumber'::"text")), "id", "version" DESC, "modified_at" DESC, "state_code" DESC) WHERE (("dataset_kind" = 'flow'::"text") AND ("jsonb_typeof"(("card" -> 'casNumber'::"text")) = 'string'::"text") AND (("card" ->> 'casNumber'::"text") ~ '^[0-9]{2,7}-[0-9]{2}-[0-9]$'::"text") AND (("length"(("card" ->> 'casNumber'::"text")) >= 7) AND ("length"(("card" ->> 'casNumber'::"text")) <= 12)));
